/* Export allowlist of the CLAP plugin on ELF (GNU ld / lld version script): the
 * entry point and nothing else. Hidden visibility cannot hide what a header stamps
 * default-visibility itself (libstdc++'s std:: instantiations, anira's inline members
 * when libanira is shared); this makes them local. cmake/clap.exports is the Mach-O
 * twin. See docs/sphinx/troubleshooting.rst, "Host application ships its own backend runtime". */
{
  global:
    clap_entry;
  local:
    *;
};
